 .filter(pl.col('Volume_Gal').ge(0),
         pl.col('City') == 'DECORAH')
 .select(Pct_25=pl.quantile('Volume_Gal', 0.25, interpolation='linear'),
         Pct_50=pl.col('Volume_Gal').quantile(0.5, interpolation='linear'),
         Pct_75=pl.quantile('Volume_Gal', 0.75, interpolation='linear'))
)
